export const pages = categories.flatMap((category, categoryIndex) => category.topics.map((topic, topicIndex) => {
  const [key, title, situation, objective, coreDocument, pivot, proof, boundary] = topic;
  const index = categoryIndex * 10 + topicIndex;
  const location = locations[(index + 7) % locations.length];
  return { batch: 3, index, category, key, title, situation, objective, coreDocument, pivot, proof, boundary, location, slug: `saudi-guide-w3-${key}-${location.key}.html` };
}));

function escapeHtml(value) {
  return String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}

function rotate(items, seed, count) {
  return Array.from({ length: count }, (_, offset) => items[(seed + offset) % items.length]);
}

